-- Personality interface 1. Predecessor 006; engine owns transaction and checksum.
-- Only widens the aspect-kind vocabulary; existing columns/history are unchanged.
CREATE TABLE IF NOT EXISTS "personality_profile"(branch TEXT NOT NULL,id TEXT NOT NULL,"character" TEXT NOT NULL,"framework" TEXT NOT NULL CHECK("framework" IN ('mbti-inspired')),"type_code" TEXT,"interpretation" TEXT NOT NULL CHECK("interpretation" IN ('proposed','accepted','unknown')),"note" TEXT NOT NULL,"policy_id" TEXT,"policy_version" INTEGER,PRIMARY KEY(branch,id),FOREIGN KEY(branch,id) REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"character") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "dialogue_turn"(branch TEXT NOT NULL,id TEXT NOT NULL,"speaker" TEXT NOT NULL,"listeners" TEXT NOT NULL CHECK("listeners" IS NULL OR json_valid("listeners")),"scene" TEXT,"reply_to" TEXT,"act" TEXT NOT NULL,"text" TEXT NOT NULL,"mode" TEXT NOT NULL CHECK("mode" IN ('spoken','gesture','silence')),PRIMARY KEY(branch,id),FOREIGN KEY(branch,id) REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"speaker") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"scene") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"reply_to") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "character_aspect_v7"(branch TEXT NOT NULL,id TEXT NOT NULL,"character" TEXT NOT NULL,"section" TEXT NOT NULL CHECK("section" IN ('nature','interiority','portrayal','condition','perspective','development')),"kind" TEXT NOT NULL CHECK("kind" IN ('facet','embodiment','constituent','principle','drive','commitment','preference','boundary','conflict','description','voice','mannerism','habit','pleasure','attachment','injury','fatigue','memory_disruption','recognition_disruption','intention_impairment','agency_constraint','communication','memory','question','appraisal','arousal','attention_style','comfort','emotion','expression_state','humor','regulation','self_concept','thinking_style','thought','verbal_style')),"value_status" TEXT NOT NULL CHECK("value_status" IN ('known','unknown','absent','not_applicable')),"statement" TEXT,"related_character" TEXT,"related_item" TEXT,"clock" TEXT,"valid_from" REAL,"valid_until" REAL,"ending_condition" TEXT,"phase" TEXT NOT NULL CHECK("phase" IN ('active','ended')),"change_basis" TEXT NOT NULL CHECK("change_basis" IN ('established','voluntary','compelled','deceived','disrupted','recovered','unknown')),"supersedes" TEXT,PRIMARY KEY(branch,id),FOREIGN KEY(branch,id) REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"character") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"related_character") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"related_item") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"clock") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"supersedes") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED);
INSERT INTO character_aspect_v7 SELECT * FROM character_aspect;
DROP TABLE character_aspect;
ALTER TABLE character_aspect_v7 RENAME TO character_aspect;
CREATE UNIQUE INDEX IF NOT EXISTS one_personality_profile ON personality_profile(branch,character);
INSERT INTO engine_versions(component,version) VALUES('personality_interface','1');
